def slugify(title: str) -> str:
    result = []
    separator_pending = False

    for char in title.lower():
        if char.isalnum():
            if separator_pending and result:
                result.append("-")
            result.append(char)
            separator_pending = False
        else:
            separator_pending = True

    return "".join(result)
